package main
import (
 "fmt"
 "time"
 "github.com/robfig/cron/v3"
)
func main() {
 schedule, err := cron.NewParser(cron.Minute|cron.Hour|cron.Dom|cron.Month|cron.Dow).Parse("CRON_TZ=America/New_York 30 16 * * 1-5")
 if err != nil { panic(err) }
 cases := [][2]string{{"2026-10-30T21:00:00Z","2026-11-02T21:30:00Z"},{"2027-03-12T21:00:00Z","2027-03-15T20:30:00Z"}}
 for _, c := range cases {
  from, err := time.Parse(time.RFC3339,c[0]); if err != nil { panic(err) }
  next := schedule.Next(from).UTC().Format(time.RFC3339)
  fmt.Printf("%s -> %s expected %s\n",c[0],next,c[1])
  if next != c[1] { panic("unexpected Next time") }
 }
}
